      if (rightPartStartIndex >= binStr.length) break;

      String rightSubstr = binStr.substring(rightPartStartIndex);

      int leftVal = 
          int.parse(leftChar.toString()) * 
              (1 << (binStr.length - j - 1));
      int rightVal = 
          int.tryParse(rightSubstr).unwrapOr(0);

      if (leftVal > rightVal) {
        ok = false;
        break;
      }
    }

    if (ok) result.add(i);
  }

  return result;
}

List<int> generateIntegers(int a, int b) {
