  if (a < 2 || a > 1000) return result;


  for (int i = a; i <= b && i <= 1000; i++) {
    bool isPrime = true;

    for (int j = 2; j * j <= i; j++) {
      if (i % j == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) result.add(i);
  }

  return result;
}

