List<int> generateIntegers(int a, int b) {
  if (a > b || b < 2) return [];


  List<int> result = [];

  for (int i = 0; i <= Math.abs(b - a); ++i) {

    int value = ((b >= a ? 1 : -1) * (b - a)) >> i; 
    if (value != 0 && !result.contains(value)) {
      result.add(value);

      if (Math.abs(value) == Math.abs(b - a)) break; 
    }
  }


  result.sort((x, y) => x.compareTo(y));



  return result;
}

